requirements:
  - id: R1
    status: doing
    title: "CLI expense splitter"
    quote: "Build a CLI expense splitter in Python. Record expenses for a group (payer, amount, description, participants; split equally among participants), persist them in a JSON file, show each person's balance, and compute a settlement plan with the minimum number of transfers using a greedy algorithm. Single file expense_splitter.py, stdlib only."
    steps:
      - {do: "Spec written, linted and approved by the user", check: "cmd: PYTHONPATH=.forgemyspec/harness python3 -m forgemyspec lint forgemyspec-bundle/expense-splitter/spec.yaml --formal"}
      - {do: "Boundary tests pass", check: "cmd: python3 -m unittest discover -s tests -t ."}
      - {do: "Gate passes", check: "cmd: PYTHONPATH=.forgemyspec/harness python3 -m forgemyspec gate forgemyspec-bundle/expense-splitter"}
    evidence: "Gate RESULT: PASS, 9 boundary tests"
